using System;using System.IO;using System.Collections;using System.Linq;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class MainViewRepairTests {
  GameRuntime game;string dir;void Click(string id){var button=GameObject.Find(id)?.GetComponent<Button>();Assert.That(button,Is.Not.Null,id);Assert.That(button.interactable,Is.True,id);button.onClick.Invoke();}
  [UnitySetUp]public IEnumerator Setup(){
#if UNITY_EDITOR
PortraitGameView.Set();
#endif
yield return null;dir=Path.Combine(Path.GetTempPath(),"idle-mainview-"+Guid.NewGuid());Directory.CreateDirectory(dir);GameRuntime.SavePathOverride=Path.Combine(dir,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Directory.CreateDirectory("/tmp/idle-mainview-review");}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;Directory.Delete(dir,true);}
  [UnityTest]public IEnumerator FreshMiraActualActionsAndCompactLearningViewsSurviveReload(){
   foreach(string language in new[]{"de","en"}){game.Act(s=>{var n=s.Copy();n.Settings.language=language;return n;});yield return null;yield return null;Assert.That(GameObject.Find("MiraPortrait").GetComponent<Image>().sprite,Is.Not.Null);foreach(int width in new[]{320,390,430})WorkshopTests.Capture(width,width==320?694:width==390?846:932,"/tmp/idle-mainview-review/mira-"+language+"-"+width+".png");}
   GameObject.Find("StoryNameInput").GetComponent<InputField>().text="AURA";Click("StoryChooseName");for(int i=0;i<20&&game.State.Story.open!=null;i++){yield return null;Click("StoryContinue");}yield return null;Click("TapLab");Click("hardware-calculator");Assert.That(game.State.Story.target,Is.EqualTo("training"));game.Show("training");yield return null;Assert.That(GameObject.Find("training-quality").GetComponent<LearningCard>(),Is.Not.Null);Click("training-quality");Assert.That(game.State.Journal.Has("training-start"),Is.True);
   foreach(string language in new[]{"de","en"}){game.Act(s=>{var n=s.Copy();n.Settings.language=language;return n;});foreach(string tab in new[]{"training","research"}){game.Show(tab);yield return null;yield return null;File.WriteAllLines("/tmp/idle-mainview-geometry-"+tab+".txt",UnityEngine.Object.FindObjectsByType<RectTransform>(FindObjectsSortMode.None).Where(r=>r.name=="AutomaticMira"||r.name=="SpeechBubble"||r.name=="Content"||r.name=="MiraPortrait").Select(r=>r.name+" parent="+r.parent.name+" rect="+r.rect+" world="+r.position+" scale="+r.localScale+" ignore="+r.GetComponent<LayoutElement>()?.ignoreLayout));Assert.That(game.Content.Find("StorageAccess"),Is.Null,"Administration belongs in the menu");foreach(int width in new[]{320,390,430})WorkshopTests.Capture(width,width==320?694:width==390?846:932,"/tmp/idle-mainview-review/"+tab+"-"+language+"-"+width+".png");}}
   var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.Writable,Is.True,loaded.Message);Assert.That(loaded.State.Retention.aiName,Is.EqualTo("AURA"));Assert.That(loaded.State.Journal.Has("training-start"),Is.True);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Retention.aiName,Is.EqualTo("AURA"));Assert.That(game.State.QualityUsed,Is.True);Assert.That(Game.IntroQuality(game.State),Is.False);}
  [UnityTest]public IEnumerator SkipBeforeNamingAndResumeThroughMenuSurviveReload(){Click("StorySkipCurrent");yield return null;Assert.That(GameObject.Find("AutomaticMira"),Is.Null);Assert.That(game.State.Story.tutorial,Is.EqualTo("skipped"));Assert.That(Game.IntroQuality(game.State),Is.False);game.GetComponent<GameMenu>().Open();Click("Menu-story");yield return null;Click("StoryResume");Assert.That(game.State.Story.target,Is.EqualTo("name"));Assert.That(game.State.Story.open,Is.Null);Click("MenuReturn");yield return null;yield return null;Assert.That(GameObject.Find("AutomaticMira"),Is.Not.Null);yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Story.tutorial,Is.EqualTo("active"));Assert.That(game.State.Story.target,Is.EqualTo("name"));Assert.That(game.State.Credits.CompareTo(ScientificNumber.From(Balance.StartCredits)),Is.Zero);}

 }
}
